/**
 * Normaliza o evento do provedor de WhatsApp num formato único:
 *   { phone, body, waId, name }
 *
 * Suporta a Cloud API (Meta) e a Evolution API. Se o formato mudar,
 * é o único ponto que precisa ser ajustado.
 */
const out = [];

for (const item of $input.all()) {
  const b = item.json ?? {};

  // ── WhatsApp Cloud API (Meta) ────────────────────────────
  const change = b?.entry?.[0]?.changes?.[0]?.value;
  if (change?.messages?.length) {
    const msg = change.messages[0];
    const contact = change.contacts?.[0];
    const text =
      msg.text?.body ??
      msg.button?.text ??
      msg.interactive?.list_reply?.title ??
      msg.interactive?.button_reply?.title ??
      '';
    out.push({
      json: {
        phone: msg.from,
        body: String(text).trim(),
        waId: msg.id ?? null,
        name: contact?.profile?.name ?? null,
        provider: 'cloud-api',
      },
    });
    continue;
  }

  // Status de entrega da Cloud API — vai para outro caminho.
  if (change?.statuses?.length) {
    const st = change.statuses[0];
    out.push({
      json: {
        isStatus: true,
        waId: st.id,
        status: String(st.status ?? '').toUpperCase(),
        error: st.errors?.[0]?.title ?? null,
        provider: 'cloud-api',
      },
    });
    continue;
  }

  // ── Evolution API ────────────────────────────────────────
  const data = b?.data ?? b;
  if (data?.key?.remoteJid) {
    // Ignora o que a própria instância enviou e mensagens de grupo.
    if (data.key.fromMe) continue;
    if (String(data.key.remoteJid).includes('@g.us')) continue;

    const text =
      data.message?.conversation ??
      data.message?.extendedTextMessage?.text ??
      data.message?.buttonsResponseMessage?.selectedDisplayText ??
      data.message?.listResponseMessage?.title ??
      '';
    out.push({
      json: {
        phone: String(data.key.remoteJid).split('@')[0],
        body: String(text).trim(),
        waId: data.key.id ?? null,
        name: data.pushName ?? null,
        provider: 'evolution',
      },
    });
    continue;
  }

  // ── Já normalizado (testes manuais) ──────────────────────
  if (b.phone && typeof b.body === 'string') {
    out.push({ json: { phone: String(b.phone), body: b.body.trim(), waId: b.waId ?? null, name: b.name ?? null } });
  }
}

return out;

/**
 * Assina o corpo com HMAC-SHA256 usando EMPTRA_WEBHOOK_SECRET.
 * A API do Emptra aceita a assinatura OU a chave simples; a assinatura
 * é o caminho recomendado em produção.
 */
const crypto = require('crypto');
const secret = $env.EMPTRA_WEBHOOK_SECRET || '';

return $input.all().map((item) => {
  const body = JSON.stringify(item.json);
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(body).digest('hex');
  return { json: { ...item.json, __body: body, __signature: signature } };
});

